// Purpose: ROW-066, ROW-067 and ROW-068 (REQ-031) — on the checker page, in every browser of the
// harness: an automated WCAG 2.2 AA scan (axe-core, D-009) finds no failure in the empty, checked,
// menu-open, refused and failed states; Check spelling, each highlighted word, the suggestion list,
// Ignore and Copy text work from the keyboard alone; a highlighted word is exposed to assistive
// technology as flagged and a change of the count line is announced through a live region.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) with a fresh seed per run; the failed state is reached with the network
// fake (the page's check request aborted), the refused states by an over-limit offer and by the
// harness's refused-clipboard browser fake.
//
// Test argument
// ROW-066 promise: an automated WCAG 2.2 AA scan finds no failure on the page in its empty, checked,
//   menu-open, refused and failed states (REQ-031 fail-if "an automated or manual check finds a
//   level-AA failure"; A-015).
// ROW-066 wrong product: highlights drawn with a pale yellow that fails contrast, a menu of
//   unlabelled icon buttons, or an error message in grey on white — states a scan of the empty page
//   alone never sees.
// ROW-066 given: the page driven into each state — empty; checked (two highlights shown); menu open
//   on a highlight; refused (an offer of 10,001 characters, and a Copy text with the clipboard
//   refused); failed (the page's check request aborted by the network); when: axe-core scans the whole
//   page with the WCAG 2.0/2.1/2.2 A and AA rules in each state; then: no violation in any state —
//   each state first observed (highlights, menu, message) so the scan is of that state.
// ROW-066 controls: the scan of the empty page runs and passes rules (its `passes` non-empty) — the
//   scanner sees the page; untouched by a violation in a later state.
// ROW-066 technique: every named state reached through public paths (and network or browser fakes
//   for the failures), one scan per state, all violations reported together.
// cases: ROW-066 target=ROW-066-a-wcag-2-2-aa-scan-finds-no-failure-in-the-empty-checked-menu-open-refused-and-failed-states control=ROW-066-control-the-scanner-sees-the-empty-page
//
// ROW-067 promise: Check spelling, each highlighted word, the suggestion list, Ignore and Copy text are
//   reachable and usable from the keyboard alone (REQ-031 fail-if "any of those controls cannot be
//   reached or used from the keyboard"; A-015).
// ROW-067 wrong product: highlights that are plain spans with click handlers (no tab stop, no key
//   handler), or a menu whose items are divs reachable only by mouse.
// ROW-067 given: a text with two fresh misspellings in the box and the focus in the box; when, with
//   Tab, arrow keys and Enter only: Tab to Check spelling and Enter; Tab to the first highlight and
//   Enter; arrow or Tab to a suggestion and Enter; Tab to the second highlight, Enter, arrow or Tab to
//   Ignore and Enter; Tab to Copy text and Enter; then: the check ran and drew both highlights; the
//   first word was replaced by the chosen suggestion; the second's highlight is gone and the text is
//   unchanged by it; the clipboard holds the box's text and the page confirms the copy.
// ROW-067 controls: the same text checked by pointer shows both highlights — the state the keyboard
//   path needs is reachable; untouched by a keyboard fault.
// ROW-067 technique: the engine's keyboard only after the setup's fill; each control found by its
//   identifier as the focused element, never focused by script.
// cases: ROW-067 target=ROW-067-check-each-highlight-the-suggestions-ignore-and-copy-work-from-the-keyboard-alone control=ROW-067-control-the-text-checked-by-pointer-shows-both-highlights
//
// ROW-068 promise: a highlighted word is exposed to assistive technology as flagged, and a change of
//   the count line is announced through a live region (REQ-031 fail-if "a highlighted word is not
//   announced as flagged, or a change of the count line is not announced"; A-015).
// ROW-068 wrong product: highlights that are coloured spans only (a screen reader reads the word
//   plainly), and a count line inserted with aria-live already on it (a region created with its
//   content is not announced) or with no live region at all.
// ROW-068 given: a text with two fresh misspellings; the live regions present before the check
//   recorded; when: the check is pressed, then one highlight is ignored; then: every highlight carries
//   aria-invalid (spelling, grammar or true) on itself or has an accessible name or description that
//   says it is flagged (error, falta, incorrecta, mal escrita, ortografía, marcada, revisar,
//   sugerencias), and is not hidden from assistive technology; the count line's text after the check,
//   and again after the Ignore changed it, is inside a live region that was already in the page
//   before the check.
// ROW-068 controls: the check shows both highlights and the count line — the state is reached;
//   untouched by an exposure fault.
// ROW-068 technique: accessible name and description as Playwright computes them, live-region
//   identity held across the change (an element handle taken before it).
// cases: ROW-068 target=ROW-068-a-highlight-is-exposed-as-flagged-and-a-count-change-is-announced-by-a-live-region control=ROW-068-control-the-check-shows-highlights-and-the-count

import AxeBuilder from '@axe-core/playwright';
import { expect, test, type ElementHandle, type Page } from '@playwright/test';
import { accentPopulation, asActor, compose, el, enterOffer, freshRandom, openChecker, pressCheck, readHighlights, ROLES, takeCheckSlot, type Rng } from './harness';
import {
  activeRole,
  chooseIgnore,
  flagsAt,
  isTouch,
  openMenu,
  openMenuByEnter,
  openMenuByPointer,
  readClipboard,
  readCount,
  readMessage,
  readOfferText,
  refuseClipboard,
  replacedAt,
  scratchPage,
  sprinkle,
  tabUntil,
} from './suggestions-helpers';

const WAIT_MS = 15_000;
// @axe-core/playwright types its page against its own copy of playwright-core; the object is the same page.
const axe = (page: Page) => new AxeBuilder({ page: page as unknown as ConstructorParameters<typeof AxeBuilder>[0]['page'] });
const TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22a', 'wcag22aa'];

function offer(rng: Rng) {
  const pop = accentPopulation();
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  const { text, placed } = compose(sprinkle(rng, [a.stripped, b.stripped]));
  const [pA, pB] = placed.filter((p) => p.word === a.stripped || p.word === b.stripped).sort((x, y) => x.start - y.start);
  return { text, pA, pB };
}

const listed = async (page: Page, text: string) => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`);
const isCheck = (r: { method(): string; url(): string }) => r.method() === 'POST' && new URL(r.url()).pathname === '/api/check';

async function scan(page: Page, state: string): Promise<string[]> {
  const r = await axe(page).withTags(TAGS).analyze();
  return r.violations.map((v) => `${state}: ${v.id} — ${v.help} (${v.nodes.map((n) => n.target.join(' ')).join(', ')})`);
}

test('ROW-066-a-wcag-2-2-aa-scan-finds-no-failure-in-the-empty-checked-menu-open-refused-and-failed-states', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  const found: string[] = [];

  await openChecker(page);
  found.push(...(await scan(page, 'empty')));

  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-066: the check is answered').toBe(200);
  await expect.poll(() => listed(page, text), { message: `ROW-066: the checked state shows both highlights (seed ${rng.seed})`, timeout: WAIT_MS }).toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);
  found.push(...(await scan(page, 'checked')));

  await openMenuByPointer(page, text, pA.start, 'ROW-066');
  found.push(...(await scan(page, 'menu-open')));
  await page.keyboard.press('Escape');

  const fillers = 'buscamos persona para el equipo de trabajo con experiencia en proyectos ';
  const long = fillers.repeat(Math.ceil(10_001 / fillers.length)).slice(0, 10_001);
  await enterOffer(page, long);
  await takeCheckSlot();
  if (await isTouch(page)) await el(page, ROLES.check).first().tap();
  else await el(page, ROLES.check).first().click();
  await expect.poll(() => readMessage(page), { message: 'ROW-066: the refused state (10,001 characters) shows its message', timeout: WAIT_MS }).not.toBe('');
  found.push(...(await scan(page, 'refused (over the limit)')));

  await page.route('**/api/check', (route) => route.abort('failed'));
  await enterOffer(page, text);
  if (await isTouch(page)) await el(page, ROLES.check).first().tap();
  else await el(page, ROLES.check).first().click();
  await expect.poll(() => readMessage(page), { message: 'ROW-066: the failed state (the check request failed) shows its message', timeout: WAIT_MS }).not.toBe('');
  found.push(...(await scan(page, 'failed')));
  await page.unroute('**/api/check');

  await refuseClipboard(page);
  await openChecker(page);
  await enterOffer(page, text);
  const before = await readMessage(page);
  if (await isTouch(page)) await el(page, ROLES.copy).first().tap();
  else await el(page, ROLES.copy).first().click();
  await expect.poll(() => readMessage(page), { message: 'ROW-066: the refused state (clipboard refused) shows its message', timeout: WAIT_MS }).not.toBe(before);
  found.push(...(await scan(page, 'refused (clipboard)')));

  expect(found, `ROW-066: the WCAG 2.2 AA scan finds no failure in any state (seed ${rng.seed})`).toEqual([]);
});

test('ROW-066-control-the-scanner-sees-the-empty-page', async ({ page }) => {
  asActor('anonymous');
  await openChecker(page);
  const r = await axe(page).withTags(TAGS).analyze();
  expect(r.passes.length, 'ROW-066 control: the scan of the empty page passes rules — it sees the page').toBeGreaterThan(0);
});

test('ROW-067-check-each-highlight-the-suggestions-ignore-and-copy-work-from-the-keyboard-alone', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  const scratch = await scratchPage(context);
  await openChecker(page);
  await enterOffer(page, text);
  await page.bringToFront();
  await el(page, ROLES.offer).first().focus();

  // Check spelling
  expect(await tabUntil(page, async () => (await activeRole(page)) === 'check'), 'ROW-067: Tab reaches Check spelling').toBe(true);
  await takeCheckSlot();
  const answered = page.waitForResponse((r) => isCheck(r.request()), { timeout: 30_000 });
  await page.keyboard.press('Enter');
  expect((await answered).status(), 'ROW-067: Enter on Check spelling runs the check').toBe(200);
  await expect.poll(() => listed(page, text), { message: `ROW-067: the check run from the keyboard draws both highlights (seed ${rng.seed})`, timeout: WAIT_MS }).toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);

  // a highlighted word, the suggestion list, a suggestion
  await openMenuByEnter(page, text, pA.start, 'ROW-067');
  const onSuggestion = async () => (await activeRole(page)) === 'suggestion';
  const reachedSuggestion = (await tabUntil(page, onSuggestion, 6, 'ArrowDown')) || (await tabUntil(page, onSuggestion, 10, 'Tab'));
  expect(reachedSuggestion, 'ROW-067: the keyboard reaches a suggestion in the open list').toBe(true);
  const label = await page.evaluate(() => (document.activeElement?.closest('[data-element="suggestion"]')?.textContent ?? '').trim());
  await page.keyboard.press('Enter');
  const replaced = replacedAt(text, pA, label);
  await expect.poll(() => readOfferText(page), { message: `ROW-067: Enter on the suggestion "${label}" replaces "${pA.word}"`, timeout: WAIT_MS }).toBe(replaced);

  // Ignore
  const bStart = pB.start + label.length - pA.word.length;
  await openMenuByEnter(page, replaced, bStart, 'ROW-067');
  const onIgnore = async () => (await activeRole(page)) === 'ignore';
  const reachedIgnore = (await tabUntil(page, onIgnore, 6, 'ArrowDown')) || (await tabUntil(page, onIgnore, 10, 'Tab'));
  expect(reachedIgnore, 'ROW-067: the keyboard reaches Ignore in the open list').toBe(true);
  await page.keyboard.press('Enter');
  await expect.poll(async () => (await flagsAt(page, replaced)).map((f) => f.start), { message: `ROW-067: Enter on Ignore clears "${pB.word}"'s highlight`, timeout: WAIT_MS }).not.toContain(bStart);
  expect(await readOfferText(page), 'ROW-067: Ignore leaves the text unchanged').toBe(replaced);

  // Copy text
  expect(await tabUntil(page, async () => (await activeRole(page)) === 'copy'), 'ROW-067: Tab reaches Copy text').toBe(true);
  await page.keyboard.press('Enter');
  await expect.poll(() => readMessage(page), { message: 'ROW-067: Enter on Copy text confirms the copy', timeout: WAIT_MS }).toMatch(/copiad[oa]/i);
  expect((await readClipboard(scratch)).text, 'ROW-067: Copy text from the keyboard puts the box\'s text on the clipboard').toBe(replaced);
});

test('ROW-067-control-the-text-checked-by-pointer-shows-both-highlights', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-067 control: the check is answered').toBe(200);
  await expect.poll(() => listed(page, text), { message: 'ROW-067 control: both highlights show', timeout: WAIT_MS }).toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);
});

const FLAGGED = /(error|falta|incorrect|mal\s+escrit|ortogr|marcad|revis|sugerenc)/i;

async function liveRegions(page: Page): Promise<ElementHandle[]> {
  return page.$$('[aria-live="polite"], [aria-live="assertive"], [role="status"], [role="alert"], [role="log"]');
}

async function announcedIn(regions: ElementHandle[], countText: string): Promise<boolean> {
  for (const r of regions) {
    const ok = await r.evaluate((e, t) => e.isConnected && (e.textContent ?? '').includes(t), countText);
    if (ok) return true;
  }
  return false;
}

test('ROW-068-a-highlight-is-exposed-as-flagged-and-a-count-change-is-announced-by-a-live-region', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  const regions = await liveRegions(page);

  expect((await pressCheck(page)).status, 'ROW-068: the check is answered').toBe(200);
  await expect.poll(() => listed(page, text), { message: `ROW-068: both highlights show (seed ${rng.seed})`, timeout: WAIT_MS }).toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);
  await expect.poll(async () => (await readCount(page)).shown, { message: 'ROW-068: the count line shows', timeout: WAIT_MS }).toBe(true);

  const flags = el(page, ROLES.flag);
  for (let i = 0; i < (await flags.count()); i++) {
    const f = flags.nth(i);
    const word = ((await f.textContent()) ?? '').trim();
    const attrs = await f.evaluate((e) => ({
      invalid: ['spelling', 'grammar', 'true'].includes(e.getAttribute('aria-invalid') ?? ''),
      hidden: !!e.closest('[aria-hidden="true"]') || !!e.closest('[inert]'),
    }));
    expect(attrs.hidden, `ROW-068: the highlight "${word}" is not hidden from assistive technology`).toBe(false);
    let exposed = attrs.invalid;
    if (!exposed) exposed = await expect(f).toHaveAccessibleName(FLAGGED, { timeout: 1_000 }).then(() => true, () => false);
    if (!exposed) exposed = await expect(f).toHaveAccessibleDescription(FLAGGED, { timeout: 1_000 }).then(() => true, () => false);
    expect(exposed, `ROW-068: the highlight "${word}" is exposed as flagged (aria-invalid, or a name or description saying so)`).toBe(true);
  }

  const first = (await readCount(page)).text;
  expect(await announcedIn(regions, first), `ROW-068: the count line "${first}" is inside a live region present before the check`).toBe(true);

  await openMenuByPointer(page, text, pA.start, 'ROW-068');
  await chooseIgnore(page, 'ROW-068');
  await expect.poll(async () => (await readCount(page)).text, { message: 'ROW-068: Ignore changes the count line', timeout: WAIT_MS }).not.toBe(first);
  const second = (await readCount(page)).text;
  expect(await announcedIn(regions, second), `ROW-068: the changed count line "${second}" is announced through the same live region`).toBe(true);
  await expect(openMenu(page)).toHaveCount(0);
});

test('ROW-068-control-the-check-shows-highlights-and-the-count', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-068 control: the check is answered').toBe(200);
  await expect.poll(() => listed(page, text), { message: 'ROW-068 control: both highlights show', timeout: WAIT_MS }).toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);
  await expect.poll(async () => (await readCount(page)).shown, { message: 'ROW-068 control: the count line shows', timeout: WAIT_MS }).toBe(true);
});
